    /**
     * Tests getting all LoanTransactions.
     *
     * @return    Collection
     */
    public List<LoanTransaction> testGetAll() throws Throwable {
    LOGGER.info( "LoanTransactionTest:testGetAll() - Retrieving Collection of LoanTransactions:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all LoanTransaction : " );
    List<LoanTransaction> collection  = null;

    try {
        // call the static get method on the LoanTransactionService
        collection = service.getAllLoanTransaction();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            LoanTransaction currEntity  = null;
            Iterator<LoanTransaction> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getLoanTransactionId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

